// Some portions generated by Claude

// Wherever a resource is shown with a prefix, or a blank node is shown, a copy button beside it (shown on hover and
// keyboard focus) copies the complete IRI or the blank node.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const { FakeDocument } = require('./browser-fakes.js');
const { installDetailDisclosureTemplateRuntime } = require('./workbench-detail-disclosure-runtime.js');

const scripts = require('./workbench-scripts.js').compiledScriptsDir();

function loadWorkbench(navigatorOverride) {
    const workbench = {};
    const window = { setTimeout, clearTimeout };
    const copied = [];
    const navigator = navigatorOverride
        || { clipboard: { writeText: text => { copied.push(text); return Promise.resolve(); } } };
    installDetailDisclosureTemplateRuntime(workbench);
    const context = vm.createContext({ console, URL, URLSearchParams, Promise, window, workbench, navigator,
        setTimeout, clearTimeout });
    for (const filename of ['workbenchViews.js', 'workbenchRoutes.js', 'queryStream.js', 'workbenchApp.js']) {
        vm.runInContext(fs.readFileSync(path.join(scripts, filename), 'utf8'), context, { filename });
    }
    window.workbench = context.workbench;
    return { workbench: context.workbench, copied };
}

const EX = 'http://example.org/';
const RDF = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#';
const RDFS = 'http://www.w3.org/2000/01/rdf-schema#';
const iri = value => ({ kind: 'iri', value });
const context = { basePath: '/rdf4j-workbench', repositoryId: 'a', workbench: {} };

test('a result table offers to copy prefixed IRIs and blank nodes, and nothing else', async () => {
    const { workbench, copied } = loadWorkbench();
    const document = new FakeDocument();
    const root = document.createElement('div');
    document.body.appendChild(root);
    const rows = [[iri(EX + 'a'), iri('urn:other:x'), { kind: 'bnode', value: 'stored', reference: true },
        { kind: 'bnode', value: 'b2' }, { kind: 'literal', value: 'hallo' }]];
    const table = new workbench.queryStream.ResultTable(root, {
        rowCount: () => rows.length,
        variables: () => ['a', 'b', 'c', 'd', 'e'],
        read: async (start, count) => rows.slice(start, start + count),
        namespaces: () => [{ prefix: 'ex', name: EX }]
    }, { layout: 'table' });
    await table.render();

    const buttons = Array.from(root.querySelectorAll('.resource-copy'));
    assert.deepEqual(buttons.map(button => button.getAttribute('aria-label')),
        ['Copy http://example.org/a', 'Copy <_:stored>', 'Copy _:b2'],
        'the prefixed IRI and the blank nodes, not the IRI shown in full or the literal');
    assert.deepEqual(buttons.map(button => button.getAttribute('title')), ['Copy IRI', 'Copy blank node', 'Copy blank node']);
    assert.equal(buttons[0].getAttribute('type'), 'button');
    buttons[0].dispatchEvent({ type: 'click', preventDefault() {}, stopPropagation() {} });
    buttons[2].dispatchEvent({ type: 'click', preventDefault() {}, stopPropagation() {} });
    assert.deepEqual(copied, ['http://example.org/a', '_:b2']);
    table.dispose();
});

function runtime() {
    return {
        nothing: '',
        html(strings, ...values) { return { strings: Array.from(strings), values }; },
        render(template, mount) { mount.template = template; }
    };
}

/** The template as markup, with event bindings (functions) kept so that a test can call them. */
function flatten(template, handlers) {
    if (Array.isArray(template)) {
        return template.map(entry => flatten(entry, handlers)).join('');
    }
    if (template && Array.isArray(template.strings)) {
        return template.strings.reduce((result, fragment, index) => {
            if (index >= template.values.length) {
                return result + fragment;
            }
            const value = template.values[index];
            if (typeof value === 'function') {
                handlers.push(value);
                return result + fragment + 'handler-' + (handlers.length - 1);
            }
            return result + fragment + flatten(value, handlers);
        }, '');
    }
    if (template && template.tagName) {
        return '';
    }
    return template === null || typeof template === 'undefined' ? '' : String(template);
}

function page(workbench, viewId, rows, vars, metadata) {
    const model = {
        viewId, vars, rows, rowStart: 0, rowCount: rows.length, rowTopSpacer: 0, rowBottomSpacer: 0, rowStore: null,
        namespaceMap: { 'ex:': EX, 'rdfs:': RDFS }, links: [], metadata
    };
    const mount = {};
    workbench.views.render(mount, model, context, runtime());
    const outlet = workbench.views.outletOf ? workbench.views.outletOf(mount) : null;
    const handlers = [];
    return { markup: flatten(outlet && outlet.template ? outlet.template : mount.template, handlers), handlers };
}

/** Each copy button of the markup: its accessible name and its click handler. */
function copyButtons(markup, handlers) {
    return Array.from(markup.matchAll(/<button [^>]*class="?resource-copy[^>]*>/g)).map(match => ({
        label: /aria-label="?([^"\n>]+)"?/.exec(match[0])[1].trim(),
        click: handlers[Number(/@click=handler-(\d+)/.exec(match[0])[1])]
    }));
}

test('Explore offers to copy its type chips and the members of its groups', () => {
    const { workbench, copied } = loadWorkbench();
    const graph = iri(EX + 'g');
    const rows = [
        [iri(EX + 'Class'), iri(RDF + 'type'), iri(RDFS + 'Class'), graph],
        [iri(EX + 'Sub'), iri(RDFS + 'subClassOf'), iri(EX + 'Class'), graph]
    ];
    const { markup, handlers } = page(workbench, 'explore', rows, ['subject', 'predicate', 'object', 'context'],
        { resource: 'ex:Class', 'explore-resource': '<' + EX + 'Class>', 'total-result-count': rows.length });

    const chips = markup.substring(markup.indexOf('explore-resource-card__types'));
    const chipButtons = copyButtons(chips.substring(0, chips.indexOf('</ul>')), handlers);
    assert.deepEqual(chipButtons.map(button => button.label), ['Copy ' + RDFS + 'Class']);
    const group = markup.substring(markup.indexOf('data-workbench-explore-group=subClasses'));
    const memberButtons = copyButtons(group.substring(0, group.indexOf('</section>')), handlers);
    assert.deepEqual(memberButtons.map(button => button.label), ['Copy ' + EX + 'Sub']);

    memberButtons[0].click({ currentTarget: { ownerDocument: null }, preventDefault() {}, stopPropagation() {} });
    assert.deepEqual(copied, [EX + 'Sub']);
});

// On a narrow screen a type's row becomes a card whose cells are a label column and a value column: the name and its
// buttons are one element, so the buttons stay beside the name instead of wrapping under the label.
test('the Types page keeps a type and its buttons together in one element of the cell', () => {
    const { workbench } = loadWorkbench();
    const { markup } = page(workbench, 'types', [[iri(EX + 'Product')]], ['type'], { 'total-result-count': 1 });

    const cell = /<td data-label=[^>]*>([\s\S]*?)<\/td>/.exec(markup)[1].trim();
    assert.match(cell, /^<span class="workbench-copyable">[\s\S]*<\/span>$/,
        'the cell holds a single wrapper: ' + cell.replace(/\s+/g, ' ').slice(0, 200));
    // (Add to graph, which needs the Graph page's context, follows the copy button inside the wrapper too.)
    assert.match(cell, /<a [^>]*>ex:Product<\/a>[\s\S]*class="?resource-copy/,
        'the wrapper holds the name, then the copy button');
});

/**
 * A document whose selection can be copied (document.execCommand('copy')), as on a page served over plain HTTP where
 * the browser offers no navigator.clipboard.
 */
function selectionClipboard(document, works) {
    const copied = [];
    const create = document.createElement.bind(document);
    document.createElement = (tag) => {
        const element = create(tag);
        if (String(tag).toLowerCase() === 'textarea') {
            element.select = () => { document.selectedText = element.value; };
        }
        return element;
    };
    document.execCommand = (command) => {
        if (command === 'copy' && works && typeof document.selectedText === 'string') {
            copied.push(document.selectedText);
            return true;
        }
        return false;
    };
    return copied;
}

async function clickFirstCopyButton(workbench, document) {
    const status = document.createElement('div');
    status.setAttribute('id', 'workbench-route-status');
    document.body.appendChild(status);
    const root = document.createElement('div');
    document.body.appendChild(root);
    const rows = [[iri(EX + 'a')]];
    const table = new workbench.queryStream.ResultTable(root, {
        rowCount: () => rows.length,
        variables: () => ['a'],
        read: async (start, count) => rows.slice(start, start + count),
        namespaces: () => [{ prefix: 'ex', name: EX }]
    }, { layout: 'table' });
    await table.render();
    const button = root.querySelector('.resource-copy');
    button.dispatchEvent({ type: 'click', preventDefault() {}, stopPropagation() {} });
    await new Promise(resolve => setImmediate(resolve));
    return { button, status, table };
}

test('without a clipboard (a page served over plain HTTP) the copy button copies through the selection', async () => {
    const { workbench } = loadWorkbench({});
    const document = new FakeDocument();
    const copied = selectionClipboard(document, true);

    const { button, status, table } = await clickFirstCopyButton(workbench, document);

    assert.deepEqual(copied, ['http://example.org/a']);
    assert.equal(button.getAttribute('aria-label'), 'Copied');
    assert.equal(status.textContent, 'Copied');
    assert.equal(document.body.querySelectorAll('textarea').length, 0, 'the helper text area is gone again');
    assert.equal(document.activeElement, button, 'focus returns to the copy button');
    table.dispose();
});

test('when the clipboard refuses, the copy button copies through the selection', async () => {
    const { workbench } = loadWorkbench({ clipboard: { writeText: () => Promise.reject(new Error('denied')) } });
    const document = new FakeDocument();
    const copied = selectionClipboard(document, true);

    const { button, table } = await clickFirstCopyButton(workbench, document);

    assert.deepEqual(copied, ['http://example.org/a']);
    assert.equal(button.getAttribute('aria-label'), 'Copied');
    table.dispose();
});

test('when nothing can copy, the status line says how to copy instead', async () => {
    const { workbench } = loadWorkbench({});
    const document = new FakeDocument();
    selectionClipboard(document, false);

    const { button, status, table } = await clickFirstCopyButton(workbench, document);

    assert.equal(button.getAttribute('aria-label'), 'Copy http://example.org/a');
    assert.equal(status.textContent, 'Could not copy. Select the text to copy it.');
    table.dispose();
});

test('the Types page offers to copy a prefixed type, not a type shown in full', () => {
    const { workbench, copied } = loadWorkbench();
    const { markup, handlers } = page(workbench, 'types', [[iri(EX + 'Product')], [iri('urn:other:Type')]], ['type'],
        { 'total-result-count': 2 });

    const buttons = copyButtons(markup, handlers);
    assert.deepEqual(buttons.map(button => button.label), ['Copy ' + EX + 'Product']);
    buttons[0].click({ currentTarget: { ownerDocument: null }, preventDefault() {}, stopPropagation() {} });
    assert.deepEqual(copied, [EX + 'Product']);
});
